// Проверка контакта поддержки (#c3aa39, DR-06). Почтовый клиент не открывается: проверяется адрес ссылки.
import { Page, expect } from '@playwright/test';
import { SUPPORT_EMAIL } from './data-requests.helpers';

export async function expectSupportContact(page: Page) {
  // «שאלות או בקשה אחרת? כתבו לנו: support@benjico.ai» (скрины c3aa39-T6/T7/T8)
  await expect(page.getByText(/כתבו לנו/).filter({ visible: true }).first()).toBeVisible();
  const link = page.getByRole('link', { name: SUPPORT_EMAIL }).filter({ visible: true }).first();
  await expect(link).toBeVisible();
  // «клик → mailto»: ссылка ведёт на mailto:support@benjico.ai (без плейсхолдера)
  await expect(link).toHaveAttribute('href', new RegExp(`^mailto:${SUPPORT_EMAIL.replace(/\./g, '\\.')}`));
}
